inline void enc_question(std::string& out, const Question& v, int depth) {
    out += '{';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "asker");
    out += ": ";
    esc(out, v.asker);
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "key");
    out += ": ";
    esc(out, v.key);
    if (!v.slots.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "slots");
        out += ": ";
        strmap(out, v.slots, depth + 1);
    }
    out += '\n';
    pad(out, depth);
    out += '}';
}

inline void enc_request(std::string& out, const Request& v, int depth) {
    out += '{';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "op");
    out += ": ";
    esc(out, v.op);
    if (v.ask.has_value()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "ask");
        out += ": ";
        enc_question(out, *v.ask, depth + 1);
    }
    if (v.wait) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "wait");
        out += ": ";
        out += v.wait ? "true" : "false";
    }
    if (!v.id.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "id");
        out += ": ";
        esc(out, v.id);
    }
    if (!v.option.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "option");
        out += ": ";
        esc(out, v.option);
    }
    if (!v.admin.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "admin");
        out += ": ";
        esc(out, v.admin);
    }
    out += '\n';
    pad(out, depth);
    out += '}';
}

inline void enc_answer(std::string& out, const Answer& v, int depth) {
    out += '{';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "id");
    out += ": ";
    esc(out, v.id);
    if (v.pending) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "pending");
        out += ": ";
        out += v.pending ? "true" : "false";
    }
    if (!v.option.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "option");
        out += ": ";
        esc(out, v.option);
    }
    if (v.yes) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "yes");
        out += ": ";
        out += v.yes ? "true" : "false";
    }
    if (v.kept) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "kept");
        out += ": ";
        out += v.kept ? "true" : "false";
    }
    out += '\n';
    pad(out, depth);
    out += '}';
}

inline void enc_record_metadata(std::string& out, const RecordMetadata& v, int depth) {
    out += '{';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "id");
    out += ": ";
    esc(out, v.id);
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "asker");
    out += ": ";
    esc(out, v.asker);
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "key");
    out += ": ";
    esc(out, v.key);
    if (!v.about.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "about");
        out += ": ";
        esc(out, v.about);
    }
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "text");
    out += ": ";
    esc(out, v.text);
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "options");
    out += ": ";
    strs(out, v.options, depth + 1);
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "asked");
    out += ": ";
    esc(out, v.asked);
    if (!v.option.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "option");
        out += ": ";
        esc(out, v.option);
    }
    if (!v.answered.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "answered");
        out += ": ";
        esc(out, v.answered);
    }
    if (v.kept) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "kept");
        out += ": ";
        out += v.kept ? "true" : "false";
    }
    if (v.yes) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "yes");
        out += ": ";
        out += v.yes ? "true" : "false";
    }
    out += '\n';
    pad(out, depth);
    out += '}';
}

inline void enc_response_metadata(std::string& out, const ResponseMetadata& v, int depth) {
    out += '{';
    bool first = true;
    if (!v.code.empty()) {
        first = false;
        out += '\n';
        pad(out, depth + 1);
        esc(out, "code");
        out += ": ";
        esc(out, v.code);
    }
    if (!v.error.empty()) {
        if (!first) out += ',';
        first = false;
        out += '\n';
        pad(out, depth + 1);
        esc(out, "error");
        out += ": ";
        esc(out, v.error);
    }
    if (v.answer.has_value()) {
        if (!first) out += ',';
        first = false;
        out += '\n';
        pad(out, depth + 1);
        esc(out, "answer");
        out += ": ";
        enc_answer(out, *v.answer, depth + 1);
    }
    if (!v.records.empty()) {
        if (!first) out += ',';
        first = false;
        out += '\n';
        pad(out, depth + 1);
        esc(out, "records");
        out += ": ";
        enc_list<RecordMetadata>(out, v.records, depth + 1, enc_record_metadata);
    }
    if (!first) { out += '\n'; pad(out, depth); }
    out += '}';
}

