inline void enc_operator_question(std::string& out, const OperatorQuestion& v, int depth) {
    if (wire_name(v.outcome).empty()) throw Refusal("bad_enum", 0);
    if (v.answered_by.has_value() && wire_name(*v.answered_by).empty()) throw Refusal("bad_enum", 0);
    out += '{';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "outcome");
    out += ": ";
    esc(out, std::string(wire_name(v.outcome)));
    if (v.record.has_value()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "record");
        out += ": ";
        enc_record_metadata(out, *v.record, depth + 1);
    }
    if (!v.publisher.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "publisher");
        out += ": ";
        esc(out, v.publisher);
    }
    if (v.publisher_trusted) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "publisher_trusted");
        out += ": ";
        out += v.publisher_trusted ? "true" : "false";
    }
    if (v.answered_by.has_value()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "answered_by");
        out += ": ";
        esc(out, std::string(wire_name(*v.answered_by)));
    }
    if (!v.program_description.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "program_description");
        out += ": ";
        esc(out, v.program_description);
    }
    if (!v.program_original_name.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "program_original_name");
        out += ": ";
        esc(out, v.program_original_name);
    }
    out += '\n';
    pad(out, depth);
    out += '}';
}

