inline Question decode_question(Reader& r) {
    if (r.at() != '{') r.refuse("wrong_type");
    r.enter();
    ++r.pos;
    Question v;
    std::uint32_t seen = 0;
    r.skip_ws();
    if (r.at() != '}') {
        for (;;) {
            r.skip_ws();
            if (r.at() != '"') r.refuse("malformed");
            const std::string key = r.str();
            r.skip_ws();
            if (r.at() != ':') r.refuse("malformed");
            ++r.pos;
            r.skip_ws();
            if (key == "asker") {
                if (seen & 1u) r.refuse("duplicate_field");
                seen |= 1u;
                v.asker = r.str();
            } else if (key == "key") {
                if (seen & 2u) r.refuse("duplicate_field");
                seen |= 2u;
                v.key = r.str();
            } else if (key == "slots") {
                if (seen & 4u) r.refuse("duplicate_field");
                seen |= 4u;
                v.slots = str_map(r);
            } else {
                r.refuse("unknown_field");
            }
            r.skip_ws();
            if (r.at() != ',') break;
            ++r.pos;
        }
    }
    if (r.at() != '}') r.refuse("malformed");
    ++r.pos;
    --r.depth;
    if ((seen & 3u) != 3u) r.refuse("missing_field");
    return v;
}

inline Request decode_request(Reader& r) {
    if (r.at() != '{') r.refuse("wrong_type");
    r.enter();
    ++r.pos;
    Request v;
    std::uint32_t seen = 0;
    r.skip_ws();
    if (r.at() != '}') {
        for (;;) {
            r.skip_ws();
            if (r.at() != '"') r.refuse("malformed");
            const std::string key = r.str();
            r.skip_ws();
            if (r.at() != ':') r.refuse("malformed");
            ++r.pos;
            r.skip_ws();
            if (key == "op") {
                if (seen & 1u) r.refuse("duplicate_field");
                seen |= 1u;
                v.op = r.str();
            } else if (key == "ask") {
                if (seen & 2u) r.refuse("duplicate_field");
                seen |= 2u;
                v.ask = decode_question(r);
            } else if (key == "wait") {
                if (seen & 4u) r.refuse("duplicate_field");
                seen |= 4u;
                v.wait = r.boolean();
            } else if (key == "id") {
                if (seen & 8u) r.refuse("duplicate_field");
                seen |= 8u;
                v.id = r.str();
            } else if (key == "option") {
                if (seen & 16u) r.refuse("duplicate_field");
                seen |= 16u;
                v.option = r.str();
            } else if (key == "admin") {
                if (seen & 32u) r.refuse("duplicate_field");
                seen |= 32u;
                v.admin = r.str();
            } else {
                r.refuse("unknown_field");
            }
            r.skip_ws();
            if (r.at() != ',') break;
            ++r.pos;
        }
    }
    if (r.at() != '}') r.refuse("malformed");
    ++r.pos;
    --r.depth;
    if ((seen & 1u) != 1u) r.refuse("missing_field");
    return v;
}

inline Answer decode_answer(Reader& r) {
    if (r.at() != '{') r.refuse("wrong_type");
    r.enter();
    ++r.pos;
    Answer v;
    std::uint32_t seen = 0;
    r.skip_ws();
    if (r.at() != '}') {
        for (;;) {
            r.skip_ws();
            if (r.at() != '"') r.refuse("malformed");
            const std::string key = r.str();
            r.skip_ws();
            if (r.at() != ':') r.refuse("malformed");
            ++r.pos;
            r.skip_ws();
            if (key == "id") {
                if (seen & 1u) r.refuse("duplicate_field");
                seen |= 1u;
                v.id = r.str();
            } else if (key == "pending") {
                if (seen & 2u) r.refuse("duplicate_field");
                seen |= 2u;
                v.pending = r.boolean();
            } else if (key == "option") {
                if (seen & 4u) r.refuse("duplicate_field");
                seen |= 4u;
                v.option = r.str();
            } else if (key == "yes") {
                if (seen & 8u) r.refuse("duplicate_field");
                seen |= 8u;
                v.yes = r.boolean();
            } else if (key == "kept") {
                if (seen & 16u) r.refuse("duplicate_field");
                seen |= 16u;
                v.kept = r.boolean();
            } else {
                r.refuse("unknown_field");
            }
            r.skip_ws();
            if (r.at() != ',') break;
            ++r.pos;
        }
    }
    if (r.at() != '}') r.refuse("malformed");
    ++r.pos;
    --r.depth;
    if ((seen & 1u) != 1u) r.refuse("missing_field");
    return v;
}

